import React, { useState, useEffect } from 'react';
import Typewriter from 'typewriter-effect';
import Fade from 'react-reveal';
import endpoints from '../constants/endpoints';
import Social from './Social';
import FallbackSpinner from './FallbackSpinner';

const styles = {
  nameStyle: {
    fontSize: '5em',
    textAlign: 'center',
    width: '100%',
  },
  inlineChild: {
    display: 'inline-block',
  },
  mainContainer: {
    height: '100vh',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
  },
  typewriterContainer: {
    display: 'flex',
    flexDirection: 'row',
    justifyContent: 'center',
    alignItems: 'center',
    marginTop: '20px',
  },
  socialContainer: {
    marginTop: '40px',
  },
};

function Home() {
  const [data, setData] = useState(null);

  useEffect(() => {
    fetch(endpoints.home, {
      method: 'GET',
    })
      .then((res) => res.json())
      .then((res) => setData(res))
      .catch((err) => err);
  }, []);

  return data ? (
    <Fade>
      <div style={styles.mainContainer} id="home">
        <h1 style={styles.nameStyle}>{data?.name}</h1>
        <div style={styles.typewriterContainer}>
          <h2 style={{...styles.inlineChild, marginTop: 8, display: 'flex', alignItems: 'center'}}>I&apos;m&nbsp;</h2>
          <Typewriter
            options={{
              loop: true,
              autoStart: true,
              strings: data?.roles,
            }}
          />
        </div>
        <div style={styles.socialContainer}>
          <Social />
        </div>
      </div>
    </Fade>
  ) : <FallbackSpinner />;
}

export default Home;
